class MultiHeadBranch(nn.Module):
  def __init__(self):
    super().__init__()
    self.heads = nn.ModuleDict({
        'vision': nn.Linear(512, 10),
        'text': nn.Linear(768, 10),
    })

  def forward(self, x, head_name):
    return self.heads[head_name](x)

model = MultiHeadBranch()
