output = model(x_text, head_name='text')

print(output.shape)  # torch.Size([4, 10])

import torch
import torch.nn as nn

class CustomWeights(nn.Module):
  def __init__(self, num_params, dim):
    super().__init__()
    # Register list of standalone raw weight tensors
    self.params = nn.ParameterList(
        [nn.Parameter(torch.randn(dim, dim)) for _ in range(num_params)]
    )

  def forward(self, x):
    for p in self.params:
      x = torch.matmul(x, p)
    return x

model = CustomWeights(num_params=3, dim=16)
x = torch.randn(4, 16)
print(model(x).shape)  # torch.Size([4, 16])

import torch
import torch.nn as nn
import torch.optim as optim

class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.backbone = nn.Linear(10, 10)
        self.head = nn.Linear(10, 2)

    def forward(self, x):
        return self.head(self.backbone(x))

model = Net()
optimizer = optim.AdamW([
    {'params': model.backbone.parameters(), 'lr': 1e-5},
    {'params': model.head.parameters(), 'lr': 1e-3}
])

for group in optimizer.param_groups:
    print(group['lr'])

