import torch
from torch.utils.data import IterableDataset, DataLoader
from typing import Iterator

class StreamDataset(IterableDataset):
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

    def __iter__(self) -> Iterator[torch.Tensor]:
        for i in range(self.start, self.end):
            yield torch.tensor([i], dtype=torch.float32)

dataset = StreamDataset(start=0, end=10)
loader = DataLoader(dataset, batch_size=2)
for batch in loader:
    print(batch)

import torch
from torch.utils.data import Sampler, TensorDataset, DataLoader
from typing import Iterator

class ReverseSampler(Sampler[int]):
    def __init__(self, data_source):
        self.data_source = data_source

    def __iter__(self) -> Iterator[int]:
        return iter(range(len(self.data_source) - 1, -1, -1))

    def __len__(self) -> int:
        return len(self.data_source)

dataset = TensorDataset(torch.arange(5))
sampler = ReverseSampler(dataset)
loader = DataLoader(dataset, batch_size=1, sampler=sampler)

for batch in loader:
    print(batch[0].item())

import torch
import torch.nn as nn

class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Linear(10, 5)
        self._init_weights()

    def _init_weights(self):
        nn.init.xavier_uniform_(self.fc.weight, gain=nn.init.calculate_gain('tanh'))
        if self.fc.bias is not None:
            nn.init.zeros_(self.fc.bias)

model = Model()
print(f"Weight std: {model.fc.weight.std().item():.4f}")

